import struct, json, sys

def read_varint(data, pos):
    x = data[pos]
    if x < 0x80:
        return x, 1
    r = x & 0x7f
    for i in range(1,9):
        b = data[pos+i]
        if b < 0x80:
            return (r << (7*i)) | b, i+1
        r = (r << 7) | (b & 0x7f)
    return (r << 56) | data[pos+9], 10

def parse_record(data, pos, maxlen):
    hdr, nh = read_varint(data, pos)
    if hdr > maxlen - nh: raise ValueError('hdr exceeds')
    p = pos + nh
    serials = []
    for _ in range(hdr-1):
        s, n = read_varint(data, p); serials.append(s); p += n
    body = pos + hdr
    vals = []
    for s in serials:
        if body > maxlen: raise ValueError('body beyond end')
        if s == 0: vals.append(None)
        elif s == 1: vals.append(struct.unpack('>b',data[body:body+1])[0]); body+=1
        elif s == 2: vals.append(struct.unpack('>h',data[body:body+2])[0]); body+=2
        elif s == 3: vals.append(struct.unpack('>i',data[body:body+3])[0]); body+=3
        elif s == 4: vals.append(struct.unpack('>i',data[body:body+4])[0]); body+=4
        elif s == 5: vals.append(struct.unpack('>q',data[body:body+6])[0]); body+=6
        elif s == 6: vals.append(struct.unpack('>q',data[body:body+8])[0]); body+=8
        elif s == 7: vals.append(struct.unpack('>d',data[body:body+8])[0]); body+=8
        elif s == 8: vals.append(0)
        elif s == 9: vals.append(1)
        elif s >= 12 and s % 2 == 0:
            ln=(s-12)//2; vals.append(data[body:body+ln]); body+=ln
        elif s >= 13:
            ln=(s-13)//2; vals.append(data[body:body+ln].decode('utf-8','replace')); body+=ln
        else: vals.append(('?',s))
    return vals

def parse_cell(data, pos, maxlen):
    pl, n = read_varint(data, pos); pos += n
    rowid, n2 = read_varint(data, pos); pos += n2
    return rowid, parse_record(data, pos, maxlen)

